sql.where:
F.QSTNR_TYPE_CD = #{qstnrTypeCd}
AND F.DEL_DT IS NULL

	AND DATE(F.REG_DT) >= #{startRegYmd}


	AND DATE(F.REG_DT) <= #{endRegYmd}


	AND F.QSTNR_NM LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.select:
